import {harness} from './whatsapp-accuracy.test-support';

const message=`Buenas tardes para un domicilio
Una sopa de menudencias
Y me regala un ejecutivo con sopa de menundecias con pollo broster pierna pernil
En ves de ensalada más papa o yuca con gaseosa colombiana
Para villa galante
Apto 150
Entrada 25
Cuánto sería para pagar por Nequi
Me envía el número gracias`;
for(const enabled of [false,true]) it(`purchase with total/transfer question, agent=${enabled}`,async()=>{
 const h=harness(undefined,enabled);
 await h.sendQueued(message);
 expect(h.replies.join('\n')).not.toMatch(/Cotizaci[oó]n|Te los agrego/i);
 expect(h.conv.sessionData.cart.map(x=>x.name)).toEqual(expect.arrayContaining(['Sopa De Menudencias','Ejecutivo Con Pollo Broaster']));
});
